// Claude's review tests for A12: the page's call counter and resolveReply. agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { createCallCounter } from './callCounter';
import { resolveReply, type RunHandler } from './reply';
import type { HandlerRequest } from '../core/handler';
import type { Mock, MockResponse } from '../core/types';

const step = (status: number, body: string): MockResponse => ({ status, headers: { 'x-s': String(status) }, body, bodyEncoding: 'text', delayMs: 0 });

function mock(id: string, extra: Partial<Mock> = {}): Mock {
  return { id, enabled: true, method: 'ANY', urlPattern: '/x/:id', response: step(200, 'fixed'), source: 'manual', createdAt: 0, ...extra };
}

describe('createCallCounter', () => {
  it('counts calls per mock', () => {
    const c = createCallCounter();
    const a = mock('a');
    const b = mock('b');
    expect([c.next(a, 'a,b'), c.next(a, 'a,b'), c.next(b, 'a,b'), c.next(a, 'a,b')]).toEqual([1, 2, 1, 3]);
  });
  it('starts a mock over when its content changes (it was saved)', () => {
    const c = createCallCounter();
    const a = mock('a');
    c.next(a, 'a');
    c.next(a, 'a');
    const edited = { ...a, response: step(201, 'new') };
    expect(c.next(edited, 'a')).toBe(1);
    expect(c.next(edited, 'a')).toBe(2);
  });
  it('starts every mock over when the list of mocks changes (another scenario)', () => {
    const c = createCallCounter();
    const a = mock('a');
    c.next(a, 'a,b');
    c.next(a, 'a,b');
    expect(c.next(a, 'a,c')).toBe(1);
    expect(c.next(a, 'a,b')).toBe(1);
  });
});

describe('resolveReply with a sequence', () => {
  const seq = mock('s', { reply: 'sequence', sequence: { steps: [step(202, 'pending'), step(200, 'done {{params.id}}')], after: 'stay' } });
  const facts = { method: 'GET', url: 'http://a.test/x/5' };

  it('answers the step for the call count', async () => {
    expect((await resolveReply(undefined, seq, facts, 1)).response).toEqual(step(202, 'pending'));
    expect((await resolveReply(undefined, seq, facts, 2)).response.body).toBe('done {{params.id}}');
    expect((await resolveReply(undefined, seq, facts, 7)).response.status).toBe(200);
  });
  it('is the first step when no count is given', async () => {
    expect((await resolveReply(undefined, seq, facts)).response.body).toBe('pending');
  });
  it('fills templates in steps when the mock asks', async () => {
    const t = { ...seq, templates: true };
    expect((await resolveReply(undefined, t, facts, 2)).response.body).toBe('done 5');
  });
  it('a sequence with no steps answers the fixed response', async () => {
    const empty = mock('e', { reply: 'sequence', sequence: { steps: [], after: 'loop' } });
    expect((await resolveReply(undefined, empty, facts, 3)).response.body).toBe('fixed');
  });
});

describe('resolveReply passes callCount to code', () => {
  it('sends the count with the request', async () => {
    const seen: HandlerRequest[] = [];
    const run: RunHandler = async (_id, request) => {
      seen.push(request);
      return { response: step(200, 'ok') };
    };
    const code = mock('c', { reply: 'code', code: 'return req.callCount' });
    await resolveReply(run, code, { method: 'GET', url: 'http://a.test/x/1' }, 4);
    await resolveReply(run, code, { method: 'GET', url: 'http://a.test/x/1' });
    expect(seen.map((r) => r.callCount)).toEqual([4, 1]);
  });
});
